#define QK_MMA(da,db,p) "wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 " WG_ACC64 "," da "," db "," p ",1,1,0,0;\n"
// one PV (RS, trans-b) wgmma line: A={P4}, B=%(desc), accumulate.
#define PV_MMA(pa,pb,pc,pd,db) "wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 " WG_ACC64 ",{" pa "," pb "," pc "," pd "}," db ",p1,1,1,1;\n"

// QK (SS), swizzle, issue+wait. A=Q,B=K both K-major B128. Single asm block (distinct desc regs).
__device__ __forceinline__ void qk_gemm_sw(float (&s)[64], uint32_t sQ_wg, uint32_t sK_base) {
    uint64_t dA0=make_smem_desc(sQ_wg+qk_kstep(0),SW_QK_LBO,SW_QK_SBO,1), dA1=make_smem_desc(sQ_wg+qk_kstep(1),SW_QK_LBO,SW_QK_SBO,1);
    uint64_t dA2=make_smem_desc(sQ_wg+qk_kstep(2),SW_QK_LBO,SW_QK_SBO,1), dA3=make_smem_desc(sQ_wg+qk_kstep(3),SW_QK_LBO,SW_QK_SBO,1);
    uint64_t dA4=make_smem_desc(sQ_wg+qk_kstep(4),SW_QK_LBO,SW_QK_SBO,1), dA5=make_smem_desc(sQ_wg+qk_kstep(5),SW_QK_LBO,SW_QK_SBO,1);
    uint64_t dA6=make_smem_desc(sQ_wg+qk_kstep(6),SW_QK_LBO,SW_QK_SBO,1), dA7=make_smem_desc(sQ_wg+qk_kstep(7),SW_QK_LBO,SW_QK_SBO,1);
    uint64_t dB0=make_smem_desc(sK_base+qk_kstep(0),SW_QK_LBO,SW_QK_SBO,1), dB1=make_smem_desc(sK_base+qk_kstep(1),SW_QK_LBO,SW_QK_SBO,1);
    uint64_t dB2=make_smem_desc(sK_base+qk_kstep(2),SW_QK_LBO,SW_QK_SBO,1), dB3=make_smem_desc(sK_base+qk_kstep(3),SW_QK_LBO,SW_QK_SBO,1);
    uint64_t dB4=make_smem_desc(sK_base+qk_kstep(4),SW_QK_LBO,SW_QK_SBO,1), dB5=make_smem_desc(sK_base+qk_kstep(5),SW_QK_LBO,SW_QK_SBO,1);
    uint64_t dB6=make_smem_desc(sK_base+qk_kstep(6),SW_QK_LBO,SW_QK_SBO,1), dB7=make_smem_desc(sK_base+qk_kstep(7),SW_QK_LBO,SW_QK_SBO,1);
    asm volatile(
        "{\n.reg .pred p0,p1;\n setp.eq.s32 p0,1,0;\n setp.eq.s32 p1,1,1;\n"
        "wgmma.fence.sync.aligned;\n"
        QK_MMA("%64","%72","p0") QK_MMA("%65","%73","p1") QK_MMA("%66","%74","p1") QK_MMA("%67","%75","p1")
        QK_MMA("%68","%76","p1") QK_MMA("%69","%77","p1") QK_MMA("%70","%78","p1") QK_MMA("%71","%79","p1")
        "wgmma.commit_group.sync.aligned;\nwgmma.wait_group.sync.aligned 0;\n}\n"
        : WG_OUT64(s)
        : "l"(dA0),"l"(dA1),"l"(dA2),"l"(dA3),"l"(dA4),"l"(dA5),"l"(dA6),"l"(dA7),
          "l"(dB0),"l"(dB1),"l"(dB2),"l"(dB3),"l"(dB4),"l"(dB5),"l"(dB6),"l"(dB7));
