__device__ __forceinline__ void wg_fence_a(const uint32_t (&a)[32]) {
#pragma unroll
    for (int i = 0; i < 32; ++i) asm volatile("" : "+r"(const_cast<uint32_t&>(a[i])) :: "memory");
