    uint32_t lo,hi; asm("mov.b64 {%0,%1}, %2;\n":"=r"(lo),"=r"(hi):"l"(base));
    lo+=off; uint64_t r; asm("mov.b64 %0, {%1,%2};\n":"=l"(r):"r"(lo),"r"(hi)); return r; }
__device__ __forceinline__ uint64_t qk_doff(int kb){ return (uint64_t)((kb&3)*2+(kb>>2)*1024); }

