import sys, os, json, statistics, subprocess
sys.path.insert(0, "/home/yak/data-fast/agent")
import torch
from fa3agent import config as C, shapes
torch.ops.load_library(C.BASELINE_SO)
GPU=0; torch.cuda.set_device(GPU); dev=torch.device(f"cuda:{GPU}")
BIN="/home/yak/data-fast/agent/fa3agent/cutlass_oracle/kernels/fused_attn"

def time_fa3(cfg, warmup=200, iters=100, trials=5):
    inp = shapes.make_inputs(cfg, seed=0, device=f"cuda:{GPU}")
    flush = torch.empty(256*1024*1024, dtype=torch.int8, device=dev)
    s,e = torch.cuda.Event(enable_timing=True), torch.cuda.Event(enable_timing=True)
    for _ in range(warmup): shapes.call_fwd("_vllm_fa3_C", inp)
    torch.cuda.synchronize(); samp=[]
    for _ in range(trials):
        flush.zero_(); torch.cuda.synchronize(); s.record()
        for _ in range(iters): shapes.call_fwd("_vllm_fa3_C", inp)
        e.record(); torch.cuda.synchronize(); samp.append(s.elapsed_time(e)/iters)
    return statistics.median(samp)

def run_mine(B,H,S,causal,iters=200,trials=7):
    env=dict(os.environ, CUDA_VISIBLE_DEVICES=str(GPU))
    p=subprocess.run([BIN,str(S),"128",str(causal),str(B),str(H),str(iters),str(trials)],
                     stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,env=env)
    for ln in p.stdout.splitlines():
        if ln.strip().startswith("{"): return json.loads(ln)
    raise RuntimeError(p.stdout[-300:])

