        "{\n.reg .pred p;\n setp.ne.b32 p,1,0;\n"
        "wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 " WG_ACC64 ",%64,%65,p,1,1,0,1;\n}\n"
