        if (_hn) wgmma_wait1(); else wgmma_wait0();  /* PV(NB-1) drained -> P smem free */  \
        write_P_smem(sbuf[CUR], Pbase_cwg, warp, group, tg);   /* P(NB) -> smem */          \
        asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");                      \
