// ============ DBP: WST + double-buffered scores + P-in-smem with DECOUPLED K(2)/V(3) rings (-DDBP) ======
// The DBUF (double-buffered scores) overlap of softmax(nb) with PV(nb-1) AND QK(nb+1) (= 16 wgmma cover,
// vs 8 for single-score kernels incl. FA3) requires 3 live K/V blocks {nb-1,nb,nb+1}; the register cost of
// keeping P in 32 regs alongside sbuf[2][64]+acc_o[64] forced ptxas to serialize (C7511), so P is staged to
// smem (SS PV, pv_batch_ss). But P's 32KB tile + 3 coupled K+V stages (192KB) + Q (32KB) exceeds 228KB, so
// the K and V rings are DECOUPLED: K needs only 2 live blocks (QK(nb) draining + QK(nb+1) issuing) while V
// needs 3 (V(nb-1) draining + V(nb) next + V(nb+1) prefetch). K=2,V=3 -> 64+96 = 160KB + Q32 + P32 = 224KB.
// Per-ring full_K/empty_K (2) and full_V/empty_V (3) mbarriers; the producer fills each ring independently.
constexpr int KDB = 2, VDB = 3;
__global__ __launch_bounds__(NThreadsWS, 1) void fused_attn_fwd_wst_dbp(
        const __grid_constant__ CUtensorMap mapQ, const __grid_constant__ CUtensorMap mapK,
        const __grid_constant__ CUtensorMap mapV, __nv_bfloat16* __restrict__ O,
        float* __restrict__ LSE, int S, int causal, float scale, int tiles_m) {
    const int m_block = blockIdx.x;
    const int bh = blockIdx.y;
    const int row0 = m_block * CTA_M;
    __nv_bfloat16* Ob = O + (size_t)bh * S * HD;
    float* LSEb = LSE + (size_t)bh * S;

    const int tid = threadIdx.x;
    const int n_max = causal ? (m_block + 1) : tiles_m;
    const float s2 = scale * float(M_LOG2E);
    constexpr int KVSTRIDE = CTA_N * HD;

    __nv_bfloat16* sQ = smem;
    __nv_bfloat16* sK0 = smem + CTA_M * HD;
    __nv_bfloat16* sV0 = smem + CTA_M * HD + KDB * KVSTRIDE;
    __nv_bfloat16* sP  = smem + CTA_M * HD + (KDB + VDB) * KVSTRIDE;
    uint64_t* bars = reinterpret_cast<uint64_t*>(smem + (2 * CTA_M + (KDB + VDB) * CTA_N) * HD);
    uint64_t* full_K = bars;                       // [KDB]
    uint64_t* empty_K = bars + KDB;                // [KDB]
    uint64_t* full_V = bars + 2 * KDB;             // [VDB]
    uint64_t* empty_V = bars + 2 * KDB + VDB;      // [VDB]
    uint64_t* barQ = bars + 2 * KDB + 2 * VDB;     // [1]

    if (tid == 0) {
#pragma unroll
        for (int s = 0; s < KDB; ++s) { mbar_init(&full_K[s], 1); mbar_init(&empty_K[s], NumCons); }
#pragma unroll
        for (int s = 0; s < VDB; ++s) { mbar_init(&full_V[s], 1); mbar_init(&empty_V[s], NumCons); }
        mbar_init(&barQ[0], 1);
    }
    __syncthreads();

    const uint32_t st_bytes = (uint32_t)(KVSTRIDE * 2);
    const int wg = tid / WG;
    if (wg == 0) {
        // ---------------- producer: single thread, decoupled K/V TMA ----------------
        producer_regs();
        if (tid != 0) return;
        mbar_expect_tx(&barQ[0], (uint32_t)(CTA_M * HD * 2));
        tma_tile(sQ, &mapQ, bh * S + row0, &barQ[0]);
        for (int nb = 0; nb < n_max; ++nb) {
            const int krow = bh * S + nb * CTA_N;
            const int kst = nb % KDB;
            if (nb >= KDB) { const int ep = ((nb / KDB) - 1) & 1; while (!mbar_try_wait(&empty_K[kst], ep)) {} }
            mbar_expect_tx(&full_K[kst], (uint32_t)(CTA_N * HD * 2));
            tma_tile(sK0 + kst * KVSTRIDE, &mapK, krow, &full_K[kst]);
            const int vst = nb % VDB;
            if (nb >= VDB) { const int ep = ((nb / VDB) - 1) & 1; while (!mbar_try_wait(&empty_V[vst], ep)) {} }
            mbar_expect_tx(&full_V[vst], (uint32_t)(CTA_N * HD * 2));
            tma_tile(sV0 + vst * KVSTRIDE, &mapV, krow, &full_V[vst]);
        }
        return;
    }

    // ---------------- consumers ----------------
    consumer_regs();
    const int cwg = wg - 1;
    const int wtid = tid % WG, warp = wtid >> 5, lane = wtid & 31;
    const int group = lane >> 2, tg = lane & 3;
    const int row_lo = cwg * 64 + warp * 16 + group, row_hi = row_lo + 8;
    const int qlo = row0 + row_lo, qhi = row0 + row_hi;
    const uint32_t sQ_wg = (uint32_t)__cvta_generic_to_shared(sQ) + (uint32_t)(cwg * 4096 * 2);
    const uint32_t sK_a = (uint32_t)__cvta_generic_to_shared(sK0);
    const uint32_t sV_a = (uint32_t)__cvta_generic_to_shared(sV0);
    const uint32_t Pbase_cwg = (uint32_t)__cvta_generic_to_shared(sP) + (uint32_t)(cwg * 1024 * 2);
    const uint64_t baseP = make_smem_desc(Pbase_cwg, 128, 256, 0);
    const int PB = 5 + cwg;

    float acc_o[64];
#pragma unroll
    for (int i = 0; i < 64; ++i) acc_o[i] = 0.f;
    float m_r[2] = {-INFINITY, -INFINITY}, l_r[2] = {0.f, 0.f};
    float sbuf[2][64]; float sc[2];

    while (!mbar_try_wait(&barQ[0], 0)) {}
    asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");

    // ---- prologue: QK(0) -> softmax(0) -> P(0) to smem; pre-issue QK(1) ----
    while (!mbar_try_wait(&full_K[0], 0)) {}
    asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
    {
        uint64_t bA = make_smem_desc(sQ_wg, SW_QK_LBO, SW_QK_SBO, 1);
        uint64_t bB = make_smem_desc(sK_a,  SW_QK_LBO, SW_QK_SBO, 1);
        qk_batch_cute(sbuf[0], bA, bB, 0);
    }
    wgmma_wait0();
    mbar_arrive(&empty_K[0]);                       // K(0) consumed
    if (causal && m_block == 0) mask_causal(sbuf[0], 0, qlo, qhi, tg);
    sc[0] = softmax_stats(sbuf[0], m_r, l_r, 0, 0, s2);
    sc[1] = softmax_stats(sbuf[0], m_r, l_r, 1, 0, s2);
    write_P_smem(sbuf[0], Pbase_cwg, warp, group, tg);
    asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
    nbar_sync_wg(PB);
    if (n_max > 1) {
        const int kst1 = 1 % KDB;
        while (!mbar_try_wait(&full_K[kst1], (1 / KDB) & 1)) {}
        asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
        uint64_t bA = make_smem_desc(sQ_wg,                  SW_QK_LBO, SW_QK_SBO, 1);
        uint64_t bB = make_smem_desc(sK_a + kst1 * st_bytes, SW_QK_LBO, SW_QK_SBO, 1);
        qk_batch_cute(sbuf[1], bA, bB, 0);
    }

    // sbuf[CUR]=QK(NB) done; sbuf[NXT]=QK(NB+1) in flight; PV(NB-1) in flight reads P(NB-1),V(NB-1) from smem.
#define DBP_STEP(NB, CUR, NXT) do {                                                        \
        const int _vpst = ((NB) - 1) % VDB;                                                \
        const bool _hn = ((NB) + 1 < n_max);                                               \
        while (!mbar_try_wait(&full_V[_vpst], (((NB) - 1) / VDB) & 1)) {}                   \
        asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");                      \
        rescale_o(acc_o, sc);                                                              \
        { uint64_t _bV = make_smem_desc(sV_a + _vpst * st_bytes, SW_V_LBO, SW_V_SBO, 1);    \
          pv_batch_ss(acc_o, baseP, _bV); }      /* PV(NB-1) reads P(NB-1) smem */          \
        if (_hn) {                                                                         \
            const int _kst2 = ((NB) + 1) % KDB;                                            \
            while (!mbar_try_wait(&full_K[_kst2], (((NB) + 1) / KDB) & 1)) {}              \
            asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");                 \
            uint64_t _bA = make_smem_desc(sQ_wg,                   SW_QK_LBO, SW_QK_SBO, 1);\
            uint64_t _bB = make_smem_desc(sK_a + _kst2 * st_bytes, SW_QK_LBO, SW_QK_SBO, 1);\
            qk_batch_cute(sbuf[NXT], _bA, _bB, 0);                                          \
            wgmma_wait2();                       /* QK(NB) drained */                       \
        } else { wgmma_wait1(); }                /* QK(NB) drained */                       \
        mbar_arrive(&empty_K[(NB) % KDB]);       /* K(NB) free */                           \
        if (causal && (NB) == m_block) mask_causal(sbuf[CUR], (NB) * CTA_N, qlo, qhi, tg);  \
        sc[0] = softmax_stats(sbuf[CUR], m_r, l_r, 0, (NB), s2);                            \
        sc[1] = softmax_stats(sbuf[CUR], m_r, l_r, 1, (NB), s2);                            \
        if (_hn) wgmma_wait1(); else wgmma_wait0();   /* PV(NB-1) drained -> V,P free */    \
        mbar_arrive(&empty_V[_vpst]);            /* V(NB-1) free */                          \
        write_P_smem(sbuf[CUR], Pbase_cwg, warp, group, tg);   /* P(NB) -> smem */          \
        asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");                      \
        nbar_sync_wg(PB);                        /* P(NB) visible; overlaps in-flight QK(NB+1) */ \
    } while (0)

    int nb = 1;
    for (; nb + 1 < n_max; nb += 2) {
        DBP_STEP(nb,     1, 0);
        DBP_STEP(nb + 1, 0, 1);
    }
    for (; nb < n_max; ++nb) {
        DBP_STEP(nb, 1, 1);
    }
#undef DBP_STEP

    // ---- epilogue: trailing PV(n_max-1) reads P(n_max-1),V(n_max-1) from smem ----
    {
        const int vlast = (n_max - 1) % VDB;
        while (!mbar_try_wait(&full_V[vlast], ((n_max - 1) / VDB) & 1)) {}
        asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
        rescale_o(acc_o, sc);
        uint64_t baseVe = make_smem_desc(sV_a + vlast * st_bytes, SW_V_LBO, SW_V_SBO, 1);
        pv_batch_ss(acc_o, baseP, baseVe);
        asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
        wg_fence_c(acc_o);
        mbar_arrive(&empty_V[vlast]);
    }

#pragma unroll
    for (int r = 0; r < 2; ++r) {
        l_r[r] = quad_sum(l_r[r]);
        float inv = (l_r[r] == 0.f || l_r[r] != l_r[r]) ? 0.f : 1.f / l_r[r];
        int qr = row0 + (r == 0 ? row_lo : row_hi);
#pragma unroll
        for (int c = 0; c < HD / 8; ++c) {
            int dv0 = 8 * c + 2 * tg;
            uint32_t o = pack_bf16(acc_o[c*4+r*2+0] * inv, acc_o[c*4+r*2+1] * inv);
            if (qr < S) *reinterpret_cast<uint32_t*>(&Ob[(size_t)qr * HD + dv0]) = o;
        }
        if (tg == 0 && qr < S)
            LSEb[qr] = (l_r[r] == 0.f || l_r[r] != l_r[r]) ? -INFINITY : m_r[r] * scale + __logf(l_r[r]);
    }
}

