import statistics, torch, subprocess, os, json
from fa3agent import config as C, shapes
torch.ops.load_library(C.BASELINE_SO)
BIN="fa3agent/cutlass_oracle/kernels/fused_attn"
def cfg(B,H,S,causal): return C.Config(f"x_B{B}_H{H}_S{S}","prefill","bf16",128,H,H,causal=causal,paged=False,batch=B,q_len=S,k_len=S)
def time_fa3(cf,gpu=1,warmup=150,iters=100,trials=5):
    dev=torch.device(f"cuda:{gpu}"); torch.cuda.set_device(gpu)
    inp=shapes.make_inputs(cf,seed=0,device=f"cuda:{gpu}")
    fl=torch.empty(int(C.PERF["l2_flush_mb"])*1024*1024,dtype=torch.int8,device=dev)
    s,e=torch.cuda.Event(enable_timing=True),torch.cuda.Event(enable_timing=True)
    for _ in range(warmup): shapes.call_fwd("_vllm_fa3_C",inp)
    torch.cuda.synchronize(); sm=[]
    for _ in range(trials):
        fl.zero_(); torch.cuda.synchronize(); s.record()
        for _ in range(iters): shapes.call_fwd("_vllm_fa3_C",inp)
        e.record(); torch.cuda.synchronize(); sm.append(s.elapsed_time(e)/iters)
    return statistics.median(sm)
def mine(B,H,S,causal,gpu=1):
    env=dict(os.environ,CUDA_VISIBLE_DEVICES=str(gpu))
    p=subprocess.run([BIN,str(S),"128",str(causal),str(B),str(H),"100","7"],stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,env=env)
    for ln in p.stdout.splitlines():
        ln=ln.strip()
        if ln.startswith("{"): return json.loads(ln)
    raise RuntimeError(p.stdout[-300:])
print(f"{'B,H,S':>12} {'causal':>7} {'FA3 ms':>8} {'mine ms':>8} {'FA3/mine':>9} {'ok':>5}")
for (B,H,S) in [(4,16,2048),(4,16,4096),(2,16,8192),(1,16,16384)]:
