            int dv0 = 8 * c + 2 * tg;
            uint32_t o = pack_bf16(acc_o[c*4+r*2+0] * inv, acc_o[c*4+r*2+1] * inv);
            if (val) *reinterpret_cast<uint32_t*>(&O[obase + dv0]) = o;
        }
        if (tg == 0 && val)
