__device__ __forceinline__ void mbar_init(uint64_t* bar, int c) { uint32_t a = (uint32_t)__cvta_generic_to_shared(bar); asm volatile("mbarrier.init.shared.b64 [%0], %1;\n" :: "r"(a), "r"(c)); }
__device__ __forceinline__ void mbar_expect(uint64_t* bar, uint32_t bytes) { uint32_t a = (uint32_t)__cvta_generic_to_shared(bar); asm volatile("mbarrier.arrive.expect_tx.shared::cta.b64 _, [%0], %1;\n" :: "r"(a), "r"(bytes) : "memory"); }
__device__ __forceinline__ void tma_2d(void* smem, const CUtensorMap* map, int x, int y, uint64_t* bar) { uint32_t s = (uint32_t)__cvta_generic_to_shared(smem), b = (uint32_t)__cvta_generic_to_shared(bar); asm volatile("cp.async.bulk.tensor.2d.shared::cluster.global.tile.mbarrier::complete_tx::bytes [%0], [%1, {%2, %3}], [%4];\n" :: "r"(s), "l"(map), "r"(x), "r"(y), "r"(b) : "memory"); }
__device__ __forceinline__ bool mbar_wait(uint64_t* bar, int ph) { uint32_t a = (uint32_t)__cvta_generic_to_shared(bar), ok; asm volatile("{\n.reg .pred p;\nmbarrier.try_wait.parity.shared::cta.b64 p, [%1], %2;\nselp.u32 %0, 1, 0, p;\n}\n" : "=r"(ok) : "r"(a), "r"(ph)); return ok != 0; }

__global__ void load_dump(const __grid_constant__ CUtensorMap mapK, __nv_bfloat16* gChk) {
    __shared__ alignas(1024) __nv_bfloat16 sK[16384];
    __shared__ alignas(8) uint64_t bar;
    int tid = threadIdx.x;
    if (tid == 0) { mbar_init(&bar, 1); mbar_expect(&bar, 2u * 128u * 64u * sizeof(__nv_bfloat16)); tma_2d(&sK[0], &mapK, 0, 0, &bar); tma_2d(&sK[8192], &mapK, 64, 0, &bar); }
    __syncthreads();
    while (!mbar_wait(&bar, 0)) {}
    asm volatile("fence.proxy.async.shared::cta;\n" ::: "memory");
    for (int i = tid; i < 16384; i += 256) gChk[i] = sK[i];
}

static CUtensorMap make_map(const __nv_bfloat16* ptr) {
    CUtensorMap map{};
    uint64_t gdim[2] = {(uint64_t)K, (uint64_t)M};
    uint64_t gstride[1] = {(uint64_t)K * sizeof(__nv_bfloat16)};
    uint32_t bdim[2] = {64u, 128u};
    uint32_t estride[2] = {1, 1};
    CUresult cr = cuTensorMapEncodeTiled(&map, CU_TENSOR_MAP_DATA_TYPE_BFLOAT16, 2, (void*)ptr, gdim, gstride, bdim, estride, CU_TENSOR_MAP_INTERLEAVE_NONE, CU_TENSOR_MAP_SWIZZLE_128B, CU_TENSOR_MAP_L2_PROMOTION_L2_128B, CU_TENSOR_MAP_FLOAT_OOB_FILL_NONE);
    if (cr != CUDA_SUCCESS) { const char* s; cuGetErrorString(cr, &s); std::fprintf(stderr, "encode: %s\n", s); std::exit(2); }
    return map;
}

