// FA3 warp-scheduler ping-pong (mainloop_fwd_sm90: warp_scheduler_barrier_{sync,arrive}). The two
// math warpgroups share the SM's tensor cores; a hardware named barrier (bar.sync/arrive over both
// WGs = 2*WG threads) brackets each WG's GEMM-issue so that while one WG runs softmax on the FMA/SFU
// pipe, the other issues wgmma on the tensor pipe (instead of both lock-stepping). Barrier ids 1,2
// (0 is __syncthreads); each WG `sync`s its own id and `arrive`s the other's; WG0 is kicked off once.
__device__ __forceinline__ void nb_sync2(int id) { asm volatile("bar.sync %0, %1;\n" :: "r"(id), "r"(2 * WG) : "memory"); }
__device__ __forceinline__ void nb_arrive2(int id) { asm volatile("bar.arrive %0, %1;\n" :: "r"(id), "r"(2 * WG) : "memory"); }

