// ---- head-dim-generic helpers (HD,HDV multiples of 64; QK is always m64n128k16 over keys, only the
// k-step count = HD/16 changes; PV is split into HDV/64 independent m64n64k16 output boxes) --------
template <int HDt>
__device__ __forceinline__ void qk_batch_g(float (&s)[64], uint64_t baseA, uint64_t baseB, int p0) {
    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
#pragma unroll
    for (int kb = 0; kb < HDt / 16; ++kb) {
        uint64_t dA = desc_add(baseA, (uint32_t)qk_doff(kb));
        uint64_t dB = desc_add(baseB, (uint32_t)qk_doff(kb));
        int scaleD = (kb == 0) ? p0 : 1;
        asm volatile(
        "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
        "wgmma.mma_async.sync.aligned.m64n128k16.f32.bf16.bf16 " PF_ACC64 ",%64,%65,p,%67,%68,%69,%70;\n}\n"
        : PF_OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1),"n"(0),"n"(0));
    }
    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
}
// One 64-col output box: 8x m64n64k16 wgmma accumulating into acc[O..O+31] (O compile-time).
template <int O, int N>
__device__ __forceinline__ void pv_box64(float (&acc)[N], const uint32_t (&P)[32], uint64_t baseV) {
    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
#pragma unroll
    for (int kb = 0; kb < CTA_N / 16; ++kb) {
        uint64_t dB = desc_add(baseV, (uint32_t)v_doff(kb));
        asm volatile(
        "{\n.reg .pred p;\n setp.ne.b32 p, %37, 0;\n"
        "wgmma.mma_async.sync.aligned.m64n64k16.f32.bf16.bf16 " PF_ACC32 ",{%32,%33,%34,%35},%36,p,%38,%39,%40;\n}\n"
        : PF_OUT32(acc, O)
        : "r"(P[kb*4+0]),"r"(P[kb*4+1]),"r"(P[kb*4+2]),"r"(P[kb*4+3]),"l"(dB),"r"(1),"n"(1),"n"(1),"n"(1));
    }
    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
}
template <int N>
__device__ __forceinline__ void rescale_o_g(float (&acc_o)[N], const float* sc) {
#pragma unroll
    for (int c = 0; c < N / 4; ++c) {
        acc_o[c*4+0] *= sc[0]; acc_o[c*4+1] *= sc[0];
        acc_o[c*4+2] *= sc[1]; acc_o[c*4+3] *= sc[1];
    }
}
// First K-block: QK only (s = Q.K^T), HD-generic.
template <int HDt>
__device__ __forceinline__ void qk_gemm_g(float (&s)[64], uint32_t sQ_wg, uint32_t sK_base) {
    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
    qk_batch_g<HDt>(s, baseA, baseB, 0);
    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
    wg_fence_c(s);
}
// Fused QK (next block) + rescale O + PV (current block), HD/HDV-generic. acc_o has HDV/2 regs.
template <int HD, int HDV>
__device__ __forceinline__ void qk_rs_pv_g(float (&s)[64], float (&acc_o)[HDV/2], const uint32_t (&P)[32],
                                           uint32_t sQ_wg, uint32_t sK_base, uint32_t sV_base, const float* sc) {
    uint64_t baseA = make_smem_desc(sQ_wg,   SW_QK_LBO, SW_QK_SBO, 1);
    uint64_t baseB = make_smem_desc(sK_base, SW_QK_LBO, SW_QK_SBO, 1);
    qk_batch_g<HD>(s, baseA, baseB, 0);
    rescale_o_g(acc_o, sc);
    pv_box64<0>(acc_o, P, make_smem_desc(sV_base,                 SW_V_LBO, SW_V_SBO, 1));
    if constexpr (HDV >= 128) pv_box64<32>(acc_o, P, make_smem_desc(sV_base + (uint32_t)(1*8192*2), SW_V_LBO, SW_V_SBO, 1));
    if constexpr (HDV >= 192) pv_box64<64>(acc_o, P, make_smem_desc(sV_base + (uint32_t)(2*8192*2), SW_V_LBO, SW_V_SBO, 1));
    if constexpr (HDV >= 256) pv_box64<96>(acc_o, P, make_smem_desc(sV_base + (uint32_t)(3*8192*2), SW_V_LBO, SW_V_SBO, 1));
}
// Final PV (last block, after the loop), HDV-generic.
template <int HDV>
__device__ __forceinline__ void pv_final_g(float (&acc_o)[HDV/2], const uint32_t (&P)[32], uint32_t sV_base) {
    pv_box64<0>(acc_o, P, make_smem_desc(sV_base,                 SW_V_LBO, SW_V_SBO, 1));
    if constexpr (HDV >= 128) pv_box64<32>(acc_o, P, make_smem_desc(sV_base + (uint32_t)(1*8192*2), SW_V_LBO, SW_V_SBO, 1));
    if constexpr (HDV >= 192) pv_box64<64>(acc_o, P, make_smem_desc(sV_base + (uint32_t)(2*8192*2), SW_V_LBO, SW_V_SBO, 1));
    if constexpr (HDV >= 256) pv_box64<96>(acc_o, P, make_smem_desc(sV_base + (uint32_t)(3*8192*2), SW_V_LBO, SW_V_SBO, 1));
    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
    wg_fence_c(acc_o);
    wg_fence_a(P);
}

