    asm volatile("wgmma.wait_group.sync.aligned 0;\n" ::: "memory");
    wg_fence_c(s);
}
// Fused QK (next block) + rescale O + PV (current block), HD/HDV-generic. acc_o has HDV/2 regs.
template <int HD, int HDV>
__device__ __forceinline__ void qk_rs_pv_g(float (&s)[64], float (&acc_o)[HDV/2], const uint32_t (&P)[32],
                                           uint32_t sQ_wg, uint32_t sK_base, uint32_t sV_base, const float* sc) {
