// ============================ native fp8 (e4m3) prefill path ============================
// QK and PV both run on the fp8 tensor core (2x bf16 throughput). The f32 accumulator layout for
// m64n128k32.e4m3 is identical to the bf16 m64n128k16 one, so softmax/mask/epilogue are unchanged.
// fp8 1-byte 128B swizzle: 128 fp8 = one 128B row; the 16-byte (16-fp8) chunk is swizzled by row&7.
// For hd128/CTA_N=128 every operand tile (Q,K,Vt,P) is a [128-row,128-col] K-major fp8 tile. The
// whole recipe (koff8 + LBO16/SBO1024/lt=1 + k32 step=kb*32 + V-transpose + P-in-smem SS-PV) is
// validated bit-exact vs a CPU fp8 GEMM in kernels/fp8_probe.cu.
__device__ __forceinline__ int koff8(int row, int c) {
    return (c >> 7) * (128 * CTA_N) + row * 128 + ((c & 127) ^ ((row & 7) << 4));
}
constexpr uint32_t SW8_LBO = 16, SW8_SBO = 1024;
__device__ __forceinline__ void wg_barrier(int id) {
    asm volatile("bar.sync %0, 128;\n" :: "r"(id) : "memory");
}
// QK: s[64] = Q.K^T (m64n128k32 e4m3 SS over HD; first k-block overwrites, rest accumulate).
template <int HDt>
__device__ __forceinline__ void qk_fp8_ss(float (&s)[64], uint32_t sQ_wg, uint32_t sK_base) {
    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
#pragma unroll
    for (int kb = 0; kb < HDt / 32; ++kb) {
        uint32_t off = (uint32_t)(kb * 32);
        uint64_t dA = make_smem_desc(sQ_wg + off, SW8_LBO, SW8_SBO, 1);
        uint64_t dB = make_smem_desc(sK_base + off, SW8_LBO, SW8_SBO, 1);
        int scaleD = (kb == 0) ? 0 : 1;
        asm volatile(
        "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
        "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",%64,%65,p,%67,%68;\n}\n"
        : PF_OUT64(s) : "l"(dA),"l"(dB),"r"(scaleD),"n"(1),"n"(1));
    }
    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
}
// PV: acc_o[64] += P.V (m64n128k32 e4m3 SS over CTA_N keys; A=P[q][key], B=Vt[dv][key]). Always
// accumulates (acc_o holds the running online-attention output, pre-scaled by the softmax correction).
__device__ __forceinline__ void pv_fp8_ss(float (&acc_o)[64], uint32_t sP_wg, uint32_t sV_base) {
    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
#pragma unroll
    for (int kb = 0; kb < CTA_N / 32; ++kb) {
        uint32_t off = (uint32_t)(kb * 32);
        uint64_t dA = make_smem_desc(sP_wg + off, SW8_LBO, SW8_SBO, 1);
        uint64_t dB = make_smem_desc(sV_base + off, SW8_LBO, SW8_SBO, 1);
        asm volatile(
        "{\n.reg .pred p;\n setp.ne.b32 p, %66, 0;\n"
        "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",%64,%65,p,%67,%68;\n}\n"
        : PF_OUT64(acc_o) : "l"(dA),"l"(dB),"r"(1),"n"(1),"n"(1));
    }
    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
}
// Scatter softmax probabilities (in the C-accumulator layout) into the K-major fp8 P tile sP.
// Two adjacent key-cols share a byte pair => one st.shared.u16 (koff8 is even at col=8c+2tg).
__device__ __forceinline__ void scatter_P_fp8(const float (&s)[64], uint32_t sP_wg_addr,
                                              int warp, int group, int tg) {
#pragma unroll
    for (int c = 0; c < CTA_N / 8; ++c)
#pragma unroll
        for (int r = 0; r < 2; ++r) {
            int row = warp * 16 + group + r * 8;
            int col = 8 * c + 2 * tg;
            __nv_fp8_e4m3 a(s[c*4+r*2+0]), b(s[c*4+r*2+1]);
            uint16_t packed = (uint16_t)a.__x | ((uint16_t)b.__x << 8);
            uint32_t dst = sP_wg_addr + (uint32_t)koff8(row, col);
            asm volatile("st.shared.u16 [%0], %1;\n" :: "r"(dst), "h"(packed) : "memory");
        }
}
// Load one V row V[key][0..HDVt) (coalesced uint4) and scatter into the transposed K-major tile
// sVt[dv][key] (byte scatter: dv is the row, key the contiguous-swizzled col).
template <int HDVt>
__device__ __forceinline__ void gather_v_transpose8(__nv_fp8_e4m3* sVt, int key,
                                                    const __nv_fp8_e4m3* src, bool valid) {
#pragma unroll
    for (int c16 = 0; c16 < HDVt / 16; ++c16) {
        uint4 chunk = valid ? *reinterpret_cast<const uint4*>(src + c16 * 16) : make_uint4(0, 0, 0, 0);
        const __nv_fp8_e4m3* cv = reinterpret_cast<const __nv_fp8_e4m3*>(&chunk);
#pragma unroll
        for (int e = 0; e < 16; ++e) sVt[koff8(c16 * 16 + e, key)] = cv[e];
    }
}
// Gather one K-major fp8 row (HDt elems) into the swizzled tile (raw 16-byte copy, koff8).
template <int HDt>
__device__ __forceinline__ void gather_row_k8(__nv_fp8_e4m3* sbase, int row,
                                              const __nv_fp8_e4m3* src, bool valid) {
#pragma unroll
    for (int c16 = 0; c16 < HDt / 16; ++c16) {
        uint4 v = valid ? *reinterpret_cast<const uint4*>(src + c16 * 16) : make_uint4(0, 0, 0, 0);
        *reinterpret_cast<uint4*>(sbase + koff8(row, c16 * 16)) = v;
    }
}

extern __shared__ __align__(1024) __nv_bfloat16 pf_smem[];

