// Flash-combine the per-split normalized partials into the final O/LSE. One warp per (qidx, head).
template <typename TOut, int HDV>
__global__ void combine_kernel(
        const float* __restrict__ Opart, const float* __restrict__ LSEpart,
        TOut* __restrict__ O, float* __restrict__ LSE,
        int num_splits, int total_q, int hq, long o_row, long o_head) {
    constexpr int perv = HDV / 32;
    const int witem = blockIdx.x * WARPS_PER_BLOCK + (threadIdx.x >> 5);
    const int lane = threadIdx.x & 31;
    if (witem >= total_q * hq) return;
    const int qidx = witem / hq, head = witem % hq;

    float lmax = -INFINITY;
    for (int s = 0; s < num_splits; ++s)
        lmax = fmaxf(lmax, LSEpart[((long)s * hq + head) * total_q + qidx]);

    float acc[perv];
#pragma unroll
    for (int e = 0; e < perv; ++e) acc[e] = 0.f;
    float denom = 0.f;
    if (lmax > -INFINITY) {
        for (int s = 0; s < num_splits; ++s) {
            float lse = LSEpart[((long)s * hq + head) * total_q + qidx];
            float w = __expf(lse - lmax);
            if (w == 0.f) continue;
            denom += w;
            const float* op = Opart + (((long)s * total_q + qidx) * hq + head) * HDV;
#pragma unroll
            for (int e = 0; e < perv; ++e) acc[e] += w * op[lane * perv + e];
        }
    }
    const float inv = denom > 0.f ? 1.f / denom : 0.f;
    TOut* o = O + (long)qidx * o_row + (long)head * o_head;
#pragma unroll
    for (int e = 0; e < perv; ++e) o[lane * perv + e] = from_float<TOut>(acc[e] * inv);
    if (lane == 0)
        LSE[(long)head * total_q + qidx] = (denom > 0.f) ? (lmax + __logf(denom)) : -INFINITY;
}

