// Flash-combine the per-split normalized partials into the final O/LSE (FA3 hopper combine design,
// flash_fwd_combine_kernel.h). The old kernel ran 128 threads per (qidx,head) reading fp32 O
// partials straight from gmem with no pipelining -> DRAM-latency starved (~40% of decode time,
// DRAM <2% on hd256), and for HDV=128 left half the threads idle (TILE=64 < 128). Mirroring FA3:
//   * tile = BM rows of (qidx,head) x BK head-dim cols; grid = (ceil(total_q*hq/BM), HDV/BK). The
//     256 threads map 1:1 to one float4 each (BM x BK/4 == 256) -> every thread busy + 128-bit
//     vectorized loads.
//   * per-split softmax weights are reduced once into smem (one warp/row, shuffle) and reused.
//   * O partials stream through a kStages-deep cp.async ring -> the next splits' loads overlap the
//     current split's accumulate (the real lever on a latency-bound reduce).
// Partials stay fp32 (matches the prefill epilogue writes); only the final O store narrows to TOut.
constexpr int COMBINE_THREADS = 256;
constexpr int COMBINE_STAGES = 4;
constexpr int comb_bk(int hdv) { return hdv % 128 == 0 ? 128 : (hdv % 64 == 0 ? 64 : 32); }
constexpr int comb_bm(int hdv) { return COMBINE_THREADS / (comb_bk(hdv) / 4); }  // 8 / 16 / 32
constexpr int comb_nb(int hdv) { return hdv / comb_bk(hdv); }
// Back-compat alias (older call sites used combine_nb for the head-dim tile count).
constexpr int combine_nb(int hdv) { return comb_nb(hdv); }

template <typename TOut, int HDV>
__global__ __launch_bounds__(COMBINE_THREADS) void combine_kernel(
        const float* __restrict__ Opart, const float* __restrict__ LSEpart,
        TOut* __restrict__ O, float* __restrict__ LSE,
        int num_splits, int total_q, int hq, long o_row, long o_head) {
    constexpr int BK = comb_bk(HDV);          // head-dim cols per block
    constexpr int BM = comb_bm(HDV);          // (qidx,head) rows per block
    constexpr int TPR = BK / 4;               // threads per row (each loads one float4)
    constexpr int TILEELEMS = BM * BK;
    const int N = total_q * hq;
    const int m0 = blockIdx.x * BM;
    const int e_base = blockIdx.y * BK;
    const int tid = threadIdx.x;
    const long sstride = (long)total_q * hq * HDV;

    extern __shared__ float smem[];
    float* sW = smem;                         // [BM][num_splits] normalized weights
    float* sO = smem + BM * num_splits;       // [STAGES][BM][BK] O-partial ring
    const uint32_t sOaddr = (uint32_t)__cvta_generic_to_shared(sO);

    // ---- Phase A: per-row softmax weights (one warp per row, grid-strided over BM) ----
    const int warp = tid >> 5, lane = tid & 31;
    for (int rl = warp; rl < BM; rl += COMBINE_THREADS / 32) {
        const int witem = m0 + rl;
        const bool valid = witem < N;
        const int qidx = valid ? witem / hq : 0, head = valid ? witem % hq : 0;
        float lmax = -INFINITY;
        for (int s = lane; s < num_splits; s += 32) {
            float lse = valid ? LSEpart[((long)s * hq + head) * total_q + qidx] : -INFINITY;
            lmax = fmaxf(lmax, lse);
        }
#pragma unroll
        for (int o = 16; o > 0; o >>= 1) lmax = fmaxf(lmax, __shfl_xor_sync(0xffffffffu, lmax, o));
        float denom = 0.f;
        for (int s = lane; s < num_splits; s += 32) {
            float lse = valid ? LSEpart[((long)s * hq + head) * total_q + qidx] : -INFINITY;
            float w = (lmax > -INFINITY) ? __expf(lse - lmax) : 0.f;
            sW[rl * num_splits + s] = w;
            denom += w;
        }
#pragma unroll
        for (int o = 16; o > 0; o >>= 1) denom += __shfl_xor_sync(0xffffffffu, denom, o);
        float inv = denom > 0.f ? 1.f / denom : 0.f;
        for (int s = lane; s < num_splits; s += 32) sW[rl * num_splits + s] *= inv;  // normalize
        if (valid && lane == 0 && blockIdx.y == 0)
            LSE[(long)head * total_q + qidx] = denom > 0.f ? (lmax + __logf(denom)) : -INFINITY;
    }
    __syncthreads();

    // ---- Phase B: cp.async-pipelined weighted sum of O partials ----
    const int rl = tid / TPR;                 // this thread's row within the tile
    const int e = (tid % TPR) * 4;            // head-dim offset within the tile (one float4)
    const int witem = m0 + rl;
    const bool valid = witem < N;
    const int qidx = valid ? witem / hq : 0, head = valid ? witem % hq : 0;
    const long off0 = (((long)qidx * hq + head) * HDV) + e_base + e;   // + s*sstride
    const uint32_t myslot = (uint32_t)((rl * BK + e) * (int)sizeof(float));

    auto issue = [&](int s) {
        if (valid && s < num_splits)
            cp_async_16(sOaddr + (uint32_t)((s % COMBINE_STAGES) * TILEELEMS) * (uint32_t)sizeof(float) + myslot,
                        &Opart[(long)s * sstride + off0]);
    };
#pragma unroll
    for (int i = 0; i < COMBINE_STAGES - 1; ++i) { issue(i); cp_async_commit(); }

    float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;
    for (int s = 0; s < num_splits; ++s) {
        issue(s + COMBINE_STAGES - 1);
        cp_async_commit();
        cp_async_wait<COMBINE_STAGES - 1>();
        if (valid) {
            const float* sp = sO + (s % COMBINE_STAGES) * TILEELEMS + rl * BK + e;
            float w = sW[rl * num_splits + s];
            acc0 += w * sp[0]; acc1 += w * sp[1]; acc2 += w * sp[2]; acc3 += w * sp[3];
        }
    }
    if (valid) {
        TOut* o = O + (long)qidx * o_row + (long)head * o_head + e_base + e;
        o[0] = from_float<TOut>(acc0); o[1] = from_float<TOut>(acc1);
        o[2] = from_float<TOut>(acc2); o[3] = from_float<TOut>(acc3);
    }
}

template <typename TOut, int HDV>
static void launch_combine(const float* opd, const float* lpd, TOut* o, float* lse,
                           int num_splits, int total_q, int hq, long o_row, long o_head,
                           cudaStream_t stream) {
    constexpr int BK = comb_bk(HDV), BM = comb_bm(HDV);
    int smem = (int)((BM * num_splits + COMBINE_STAGES * BM * BK) * (int)sizeof(float));
    if (smem > 48 * 1024)
        cudaFuncSetAttribute(combine_kernel<TOut, HDV>, cudaFuncAttributeMaxDynamicSharedMemorySize, smem);
    dim3 grid((unsigned)((total_q * hq + BM - 1) / BM), (unsigned)comb_nb(HDV), 1u);
    combine_kernel<TOut, HDV><<<grid, COMBINE_THREADS, (size_t)smem, stream>>>(
        opd, lpd, o, lse, num_splits, total_q, hq, o_row, o_head);
}

