// PV box: 8x m64n64k16 accumulating into acc[O..O+31].
template <int O> __device__ __forceinline__ void pvbox(float (&acc)[64], const uint32_t (&P)[32], uint64_t baseV) {
    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
