function gm(xs: number[]): number {
  const v = xs.filter((x) => x > 0);
  return v.length ? Math.exp(v.reduce((s, x) => s + Math.log(x), 0) / v.length) : 0;
}

function tier(r: number | null): "success" | "info" | "warning" | "danger" | "neutral" {
  if (r === null) return "neutral";
  if (r >= 1.0) return "success";
  if (r >= 0.95) return "info";
  if (r >= 0.85) return "warning";
  return "danger";
}

