//   !(win_l>=0&&key<qpos-win_l) && !(win_r>=0&&key>qpos+win_r).
template <int CN = CTA_N>
__device__ __forceinline__ void pf_mask_win(float (&s)[CN/2], int col0, int qlo, int qhi, int seqlen_k,
                                            int causal, int win_l, int win_r, int tg) {
#pragma unroll
    for (int c = 0; c < CN / 8; ++c) {
        int k0 = col0 + 8 * c + 2 * tg;
        bool m00 = (k0     >= seqlen_k) || (causal && k0     > qlo) || (win_l >= 0 && k0     < qlo - win_l) || (win_r >= 0 && k0     > qlo + win_r);
        bool m10 = (k0 + 1 >= seqlen_k) || (causal && k0 + 1 > qlo) || (win_l >= 0 && k0 + 1 < qlo - win_l) || (win_r >= 0 && k0 + 1 > qlo + win_r);
        bool m01 = (k0     >= seqlen_k) || (causal && k0     > qhi) || (win_l >= 0 && k0     < qhi - win_l) || (win_r >= 0 && k0     > qhi + win_r);
        bool m11 = (k0 + 1 >= seqlen_k) || (causal && k0 + 1 > qhi) || (win_l >= 0 && k0 + 1 < qhi - win_l) || (win_r >= 0 && k0 + 1 > qhi + win_r);
        if (m00) s[c*4+0] = -INFINITY;
        if (m10) s[c*4+1] = -INFINITY;
        if (m01) s[c*4+2] = -INFINITY;
        if (m11) s[c*4+3] = -INFINITY;
    }
}

